func AncestorPath(parent []int, start int) ([]int, bool) {
	if start < 0 || start >= len(parent) {
		return nil, false
	}

	path := make([]int, 0)
	seen := make([]bool, len(parent))
	for node := start; node != -1; node = parent[node] {
		if node < 0 || node >= len(parent) {
			return nil, false
		}
		if seen[node] {
			return nil, false
		}
		seen[node] = true
		path = append(path, node)
	}
	return path, true
}

