    public static byte[] packReadings(int[] readings) {
        byte[] packed = new byte[(readings.length * 12 + 7) / 8];
        int outputBit = 0;

        for (int reading : readings) {
            for (int sourceBit = 11; sourceBit >= 0; sourceBit--) {
                if (((reading >>> sourceBit) & 1) != 0) {
                    int byteIndex = outputBit >>> 3;
                    int bitInByte = 7 - (outputBit & 7);
                    packed[byteIndex] |= (byte) (1 << bitInByte);
