import java.util.Arrays;

public final class Solution {
    private Solution() {
    }

    public interface Responder {
        void respond(byte[] nextState);
    }

    public interface Transformer {
        void apply(byte[] stateSnapshot, Responder responder);
    }

    public static byte[] runPipeline(byte[] initialState, Transformer[] transformers) {
        byte[] current = Arrays.copyOf(initialState, initialState.length);

        for (Transformer transformer : transformers) {
            byte[] snapshot = Arrays.copyOf(current, current.length);
            final byte[][] response = new byte[1][];
            final boolean[] responded = {false};

            Responder responder = nextState -> {
                if (responded[0]) {
                    throw new IllegalStateException("responder called more than once");
                }
                responded[0] = true;
                response[0] = Arrays.copyOf(nextState, nextState.length);
            };

            transformer.apply(snapshot, responder);
            if (!responded[0]) {
                throw new IllegalStateException("transformer did not respond");
            }
            current = response[0];
        }

        return Arrays.copyOf(current, current.length);
    }
}

