        if (document.isEmpty()) {
            return result;
        }

        Map<String, String> definitions = new HashMap<>();
        String[] lines = document.split("\\n", -1);
        for (String line : lines) {
            if (line.startsWith("DEF ")) {
                int equals = line.indexOf('=', 4);
                if (equals < 0) {
                    throw new IllegalArgumentException("malformed DEF line");
                }
                String name = line.substring(4, equals);
                if (!isName(name) || definitions.containsKey(name)) {
                    throw new IllegalArgumentException("invalid or repeated name");
                }
                definitions.put(name, line.substring(equals + 1));
            } else if (line.startsWith("GET ")) {
                String name = line.substring(4);
                if (!isName(name) || !definitions.containsKey(name)) {
                    throw new IllegalArgumentException("unknown or invalid name");
                }
                result.add(definitions.get(name));
            } else {
                throw new IllegalArgumentException("malformed line");
            }
        }
        return result;
    }

    private static boolean isName(String name) {
        return name.matches("[A-Za-z][A-Za-z0-9_]*");
    }
