    public static String[] transact(int initialBalance, String[] commands) {
        int balance = initialBalance;
        String activeId = null;
        int pending = 0;
        List<String> history = new ArrayList<>();
        List<String> output = new ArrayList<>();

        for (String command : commands) {
            if (command.startsWith("BEGIN ")) {
                if (activeId != null) {
                    output.add("ERROR");
                } else {
                    activeId = command.substring(6);
                    pending = 0;
                    output.add("BEGIN " + activeId);
                }
            } else if (command.startsWith("ADD ")) {
                if (activeId == null) {
                    output.add("ERROR");
                } else {
                    pending += Integer.parseInt(command.substring(4));
                    output.add("PENDING " + pending);
                }
            } else if (command.equals("COMMIT")) {
                if (activeId == null) {
                    output.add("ERROR");
                } else {
                    balance += pending;
                    history.add(activeId + "=" + balance);
                    output.add("COMMIT " + activeId + " " + balance);
                    activeId = null;
                    pending = 0;
                }
            } else if (command.equals("ROLLBACK")) {
                if (activeId == null) {
                    output.add("ERROR");
                } else {
                    output.add("ROLLBACK " + activeId + " " + balance);
                    activeId = null;
                    pending = 0;
                }
            } else {
                output.add(String.join(";", history));
            }
        }

        return output.toArray(new String[0]);
    }
}

