export function crc8Chunks(chunks: readonly Uint8Array[]): number {
    let accumulator = 0;

    for (const chunk of chunks) {
        for (const byte of chunk) {
            accumulator ^= byte;
            for (let bit = 0; bit < 8; bit++) {
                accumulator = (accumulator & 0x80) !== 0
                    ? ((accumulator << 1) ^ 0x07) & 0xff
                    : (accumulator << 1) & 0xff;
            }
        }
    }
    return accumulator;
}

export function collectOutcomes(
    tasks: ReadonlyArray<(report: (ok: boolean) => void) => void>,
    complete: (summary: { succeeded: number; failed: number }) => void,
): void {
    if (tasks.length === 0) {
        complete({ succeeded: 0, failed: 0 });
        return;
    }

    const settled = new Array<boolean>(tasks.length).fill(false);
    let completed = 0;
    let succeeded = 0;
    let failed = 0;

    tasks.forEach((task, index) => {
        task((ok: boolean): void => {
            if (settled[index]) {
                return;
            }
            settled[index] = true;

            if (ok) {
                succeeded++;
            } else {
                failed++;
            }
            completed++;

            if (completed === tasks.length) {
                complete({ succeeded, failed });
            }
        });
    });
}

export function broadcastOnce(
    message: string,
    listeners: ReadonlyArray<
        (message: string, acknowledge: () => void) => void
    >,
    complete: () => void,
): void {
    const uniqueListeners = Array.from(new Set(listeners));

    if (uniqueListeners.length === 0) {
        complete();
        return;
    }

    let acknowledged = 0;

    for (const listener of uniqueListeners) {
        let listenerAcknowledged = false;
        listener(message, (): void => {
            if (listenerAcknowledged) {
                return;
            }
            listenerAcknowledged = true;
            acknowledged++;

            if (acknowledged === uniqueListeners.length) {
                complete();
            }
        });
    }
}

