interface ParsedPair {
  key: string;
  value: string;
  index: number;
}

const COMPONENT_PATTERN = /^(?:[A-Za-z0-9_.!~*'()-]|%[0-9A-Fa-f]{2})*$/;

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function decodeComponent(component: string): string {
  if (!COMPONENT_PATTERN.test(component)) {
    throw new Error("Invalid encoded pairs");
  }
  try {
    return decodeURIComponent(component);
  } catch {
    throw new Error("Invalid encoded pairs");
  }
}

export function canonicalizeEncodedPairs(text: string): string {
  if (text === "") {
    return "";
  }

  const pairs: ParsedPair[] = text.split("&").map((segment, index) => {
    const separator = segment.indexOf("=");
    if (separator < 0 || separator !== segment.lastIndexOf("=")) {
      throw new Error("Invalid encoded pairs");
    }

    const key = decodeComponent(segment.slice(0, separator));
    const value = decodeComponent(segment.slice(separator + 1));
    if (key.length === 0) {
      throw new Error("Invalid encoded pairs");
    }
    return { key, value, index };
  });

  pairs.sort((left, right) => {
    const byKey = compareText(left.key, right.key);
    if (byKey !== 0) {
      return byKey;
    }
    const byValue = compareText(left.value, right.value);
    return byValue !== 0 ? byValue : left.index - right.index;
  });

  return pairs
    .map(({ key, value }) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");
}

function encodeCanonicalComponent(value: string): string {
    return encodeURIComponent(value)
        .replace(/[!'()*]/g, character =>
            `%${character.charCodeAt(0).toString(16).toUpperCase()}`,
        )
        .replace(/%[0-9a-f]{2}/gi, escape => escape.toUpperCase());
}

export function canonicalizeProperties(source: string): string {
    const properties = new Map<string, string>();

    for (const line of source.split(/\r?\n/)) {
        if (line === "") {
            continue;
        }

        const separator = line.indexOf("=");
        if (separator < 0) {
            throw new Error("Malformed property line");
        }

        const key = line.slice(0, separator);
        const encodedValue = line.slice(separator + 1);

        if (!/^[A-Za-z][A-Za-z0-9_-]*$/.test(key)) {
            throw new Error("Invalid property key");
        }
        if (properties.has(key)) {
            throw new Error("Duplicate property key");
        }
        if (!/^[\x20-\x7E]*$/.test(encodedValue)) {
            throw new Error("Encoded value must be ASCII");
        }

        let value: string;
        try {
            value = decodeURIComponent(encodedValue);
        } catch {
            throw new Error("Invalid URI-component value");
        }
        properties.set(key, value);
    }

    return [...properties.entries()]
        .sort(([leftKey], [rightKey]) =>
            leftKey < rightKey ? -1 : leftKey > rightKey ? 1 : 0,
        )
        .map(([key, value]) => `${key}=${encodeCanonicalComponent(value)}`)
        .join("\n");
}

