export interface Run<T> {
    value: T;
    count: number;
}

export function compressRuns<T>(
    items: readonly T[],
    same: (left: T, right: T) => boolean,
): Run<T>[] {
    const runs: Run<T>[] = [];

    for (const item of items) {
        const current = runs[runs.length - 1];
        if (current !== undefined && same(current.value, item)) {
            current.count += 1;
        } else {
            runs.push({ value: item, count: 1 });
        }
    }

    return runs;
}

export function weaveUnique<T>(
    first: readonly T[],
    second: readonly T[],
    keyOf: (item: T) => string,
): T[] {
    const result: T[] = [];
    const seen = new Set<string>();
    const rounds = Math.max(first.length, second.length);

    for (let index = 0; index < rounds; index += 1) {
        if (index < first.length) {
            const item = first[index];
            const key = keyOf(item);
            if (!seen.has(key)) {
                seen.add(key);
                result.push(item);
            }
        }

        if (index < second.length) {
            const item = second[index];
            const key = keyOf(item);
            if (!seen.has(key)) {
                seen.add(key);
                result.push(item);
            }
        }
    }

    return result;
}

