export class CodePointTape {
  private text: string;

  constructor(seed = "") {
    this.text = seed.normalize("NFC");
  }

  append(fragment: string): number {
    this.text = (this.text + fragment).normalize("NFC");
    return this.length();
  }

  pop(): string | undefined {
    const points = Array.from(this.text);
    const removed = points.pop();
    this.text = points.join("");
    return removed;
  }

  value(): string {
    return this.text;
  }

  length(): number {
    return Array.from(this.text).length;
  }

  clear(): void {
    this.text = "";
  }
}

