export function uniqueDisplayNames(values: readonly string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const raw of values) {
    const display = raw
      .normalize("NFKC")
      .replace(/\p{White_Space}+/gu, " ")
      .trim();

    if (display.length === 0) {
      continue;
    }

    const key = display.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      result.push(display);
    }
  }

  return result;
