def dependency_layers(graph: dict[str, list[str]], starts: list[str]) -> list[list[str]]:
    current = []
    discovered = set()
    for node in starts:
        if node not in discovered:
            discovered.add(node)
            current.append(node)

    layers = []
    while current:
        layers.append(current[:])
        next_layer = []
        for node in current:
            for child in graph[node]:
                if child not in discovered:
                    discovered.add(child)
                    next_layer.append(child)
        current = next_layer
    return layers

