        key = (model, variant)
        if key in seen:
            if seen[key] != score:
                raise ValueError("conflicting duplicate")
            continue

        seen[key] = score
        records.append({"model": model, "variant": variant, "score": score})

    return {"records": records}

def apply_splices(sequence, edits):
    if not isinstance(sequence, list) or not isinstance(edits, list):
        raise ValueError("arguments must be lists")

    result = []
    cursor = 0
    previous_start = -1

    for edit in edits:
        if not isinstance(edit, tuple) or len(edit) != 3:
            raise ValueError("each edit must be a 3-tuple")
        start, delete_count, replacement = edit
        if type(start) is not int or type(delete_count) is not int:
            raise ValueError("indices must be integers")
        if not isinstance(replacement, list):
            raise ValueError("replacement must be a list")
        if start < 0 or start > len(sequence):
            raise ValueError("start out of bounds")
        if delete_count < 0 or delete_count > len(sequence) - start:
            raise ValueError("delete count out of bounds")
        if start < previous_start:
            raise ValueError("edits are out of order")
        if start < cursor:
            raise ValueError("edits overlap")

        result.extend(sequence[cursor:start])
        result.extend(replacement)
        cursor = start + delete_count
        previous_start = start

    result.extend(sequence[cursor:])
    return result

def _is_index(value):
    return type(value) is int


def apply_edit_script(values, script):
    if not isinstance(values, list) or not isinstance(script, list):
        raise ValueError("arguments must be lists")

    result = list(values)
    for operation in script:
        if not isinstance(operation, tuple) or not operation:
            raise ValueError("operation must be a nonempty tuple")

        name = operation[0]
        if name == "set":
            if len(operation) != 3 or not _is_index(operation[1]):
                raise ValueError("malformed set")
            index = operation[1]
            if index < 0 or index >= len(result):
                raise ValueError("set index out of bounds")
            result[index] = operation[2]
        elif name == "insert":
            if len(operation) != 3 or not _is_index(operation[1]):
                raise ValueError("malformed insert")
            index = operation[1]
            if index < 0 or index > len(result):
                raise ValueError("insert index out of bounds")
            result.insert(index, operation[2])
        elif name == "delete":
            if len(operation) != 2 or not _is_index(operation[1]):
                raise ValueError("malformed delete")
            index = operation[1]
            if index < 0 or index >= len(result):
                raise ValueError("delete index out of bounds")
            del result[index]
        elif name == "move":
            if len(operation) != 4 or not all(_is_index(item) for item in operation[1:]):
                raise ValueError("malformed move")
            start, count, destination = operation[1:]
            if start < 0 or count <= 0 or start + count > len(result):
                raise ValueError("move range out of bounds")
            remaining_length = len(result) - count
            if destination < 0 or destination > remaining_length:
                raise ValueError("move destination out of bounds")
            block = result[start:start + count]
            del result[start:start + count]
            result[destination:destination] = block
        else:
            raise ValueError("unknown operation")

    return result

def prioritize_tasks(tasks, delayed_categories):
    delayed_categories = set(delayed_categories)
    ready = []
    delayed = []

    for task in tasks:
        if task["category"] in delayed_categories:
            delayed.append(task)
        else:
            ready.append(task)

    return ready + delayed

def weave_queues(queues):
    result = []
    width = max((len(queue) for queue in queues), default=0)

    for index in range(width):
        for queue in queues:
            if index < len(queue):
                result.append(queue[index])

    return result

class ParcelWorkflow:
    _TRANSITIONS = {
        ("created", "pack"): "packed",
        ("packed", "ship"): "shipped",
        ("shipped", "deliver"): "delivered",
        ("delivered", "reopen"): "shipped",
    }

    def __init__(self):
        self.state = "created"
        self.transition_count = 0
        self._completed = {}

    def apply(self, command_id, action):
        if command_id in self._completed:
            return self._completed[command_id]

        key = (self.state, action)
        if key not in self._TRANSITIONS:
            raise ValueError("invalid transition")

        self.state = self._TRANSITIONS[key]
        self.transition_count += 1
        result = (self.state, self.transition_count)
        self._completed[command_id] = result
        return result

