import unicodedata


def _canonicalize(text):
    normalized = unicodedata.normalize("NFKC", text).casefold()
    return " ".join(normalized.split())


def canonical_alias_index(groups):
    collected = {}
    seen = {}

    for group_name, aliases in groups.items():
        key = _canonicalize(group_name)
        if key not in collected:
            collected[key] = []
            seen[key] = set()

        for alias in aliases:
            value = _canonicalize(alias)
            if value and value not in seen[key]:
                seen[key].add(value)
                collected[key].append(value)

    return {key: tuple(values) for key, values in collected.items()}

def decode_braced_unicode(text):
    output = []
    index = 0
    hexadecimal = set("0123456789abcdefABCDEF")

    while index < len(text):
        if text[index] != "\\":
            output.append(text[index])
            index += 1
            continue

        if index + 1 < len(text) and text[index + 1] == "\\":
            output.append("\\")
            index += 2
            continue

        if text.startswith("\\u{", index):
            end = text.find("}", index + 3)
            if end == -1:
                output.append(text[index:])
                break

            candidate = text[index:end + 1]
            digits = text[index + 3:end]
            valid_digits = 1 <= len(digits) <= 6 and all(
                char in hexadecimal for char in digits
            )
            value = int(digits, 16) if valid_digits else -1
            valid_scalar = (
                valid_digits
                and value <= 0x10FFFF
                and not 0xD800 <= value <= 0xDFFF
            )
            if valid_scalar:
                output.append(chr(value))
            else:
                output.append(candidate)
            index = end + 1
            continue

        if index + 1 < len(text):
            output.append(text[index:index + 2])
            index += 2
        else:
            output.append("\\")
            index += 1

    return "".join(output)

