pub fn apportion(weights: &[u64], total: u64) -> Option<Vec<u64>> {
    if weights.is_empty() {
        return None;
    }

    let sum: u128 = weights.iter().map(|&weight| weight as u128).sum();
    if sum == 0 {
        return None;
    }

    let total_wide = total as u128;
    let mut allocations = Vec::with_capacity(weights.len());
    let mut remainders = Vec::with_capacity(weights.len());
    let mut assigned = 0u64;

    for (index, &weight) in weights.iter().enumerate() {
        let product = total_wide * weight as u128;
        let base = (product / sum) as u64;
        allocations.push(base);
        remainders.push((index, product % sum));
        assigned += base;
    }

    remainders.sort_by(|(left_index, left_remainder), (right_index, right_remainder)| {
        right_remainder
            .cmp(left_remainder)
            .then_with(|| left_index.cmp(right_index))
    });

    let remaining = total - assigned;
    for &(index, _) in remainders.iter().take(remaining as usize) {
        allocations[index] += 1;
    }

    Some(allocations)
}

