pub struct StampedDelta {
    pub position: u64,
    pub delta: i64,
}

pub fn combine_deltas(left: &[StampedDelta], right: &[StampedDelta]) -> Vec<StampedDelta> {
    let mut combined = Vec::new();
    let mut i = 0;
    let mut j = 0;

    while i < left.len() || j < right.len() {
        let position = match (left.get(i), right.get(j)) {
            (Some(a), Some(b)) => a.position.min(b.position),
            (Some(a), None) => a.position,
            (None, Some(b)) => b.position,
            (None, None) => unreachable!(),
        };

        let mut delta = 0i64;
        while i < left.len() && left[i].position == position {
            delta += left[i].delta;
            i += 1;
        }
        while j < right.len() && right[j].position == position {
            delta += right[j].delta;
            j += 1;
        }

        combined.push(StampedDelta { position, delta });
